import{_ as a,o as t,c as s,a3 as r}from"./chunks/framework.DDp5PACv.js";const u=JSON.parse('{"title":"Datasources","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"introduction.md"}'),i={name:"index.md"};function n(o,e,c,d,l,p){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="datasources" tabindex="-1">Datasources <a class="header-anchor" href="#datasources" aria-label="Permalink to &quot;Datasources&quot;">​</a></h1><p>Datasources is a data-access and object-relational mapper library. It aims for parity across <a href="./drivers.html">Languages and Datasource Providers</a>.</p><p>The <a href="./features.html#feature-stack">Feature Stack:</a> starts with commands, connections, and object mapping. Higher up, the API is more opinionated. Types and repositories are generated from a Types Specification, which can be the source of truth for the datasource schema and the generated code. The specification describes unions and inherited types. A type may contain referenced lists and dictionaries, and those references are generated as enriched repositories.</p><p>Thus, due to the well-defined <a href="./features.html#feature-stack">Feature stack</a>, the library can be used as a high-level repository builder or as a micro-ORM, alike.</p><p>The specification is declarative, so it suits generation by AI agents. Progressive skills keep that generation economical and repeatable. They use fewer tokens, and they keep generated code and mappings constant and deterministic. The library was written so TypeScript could be translated to Rust, and so data-access code written by an agent would remain coherent as an application scales.</p><div class="quick-start"><p><a href="./quickstart.html">Quick Start</a></p><p><a href="./quickstart.html#installing-the-skill">Install skill</a></p></div>',6)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
